package com.loopers.infrastructure.payment;import com.loopers.domain.payment.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import java.util.*;@Component @RequiredArgsConstructor public class PaymentIntentRepositoryImpl implements PaymentIntentRepository{private final PaymentJpaRepository jpa;public PaymentIntent save(PaymentIntent p){return jpa.save(p);}public Optional<PaymentIntent> find(long id){return jpa.findById(id);}public Optional<PaymentIntent> findByAttempt(long o,String a){return jpa.findByInternalOrderIdAndPaymentAttemptKey(o,a);}public Optional<PaymentIntent> findByProviderOrderId(String o){return jpa.findByProviderOrderId(o);}}
